globalThis.CappSolanaDocs = {"protocol":"capp.solana-developer-guide.v1","components":[{"id":"edge","name":"Solana Edge","role":"Composition","description":"Compose reviewed SOL and SPL-token payments on devnet, with durable attempts and exact receipts.","standalone":"Use Edge as a small operation coordinator, or call the other Sidecars directly. Apps retain ownership of business logic.","dependencies":"Devnet requires Circuit, Sentinel, Latch, Dispatch, Witness and Conduit. Compass is optional. Explicit demo mode can use Arena; devnet never falls back to it.","limit":"Devnet signing supports native SOL and original SPL Token Program transfers through associated token accounts. Token-2022, wrapped SOL, swaps and mainnet signing require separate providers. Exact bytes and retained attempts survive retries; token amounts are atomic strings.","methods":["status","composition","prepare","preflight","authorise","submit","transactionStatus","receipt","prepareTokenTransfer","preparePayment","refresh"]},{"id":"compass","name":"Compass","role":"Intent","description":"Shape payment and position intents, and create Solana Pay transfer requests.","standalone":"Use it to normalize application requests and preserve operation or position identity.","dependencies":"Local planning needs no peers. An external mode needs your configured adapter. Edge can shape a simple transfer when Compass is absent.","limit":"An intent does not choose a wallet, authorize a payment or establish that a trade is safe. Payment requests contain explicit network/expiry alongside a Solana Pay URI; the standard URI does not encode those constraints.","methods":["status","classify","intent","paymentRequest"]},{"id":"circuit","name":"Circuit","role":"Operation identity","description":"Reserves operation IDs, tracks attempts and protects a pending execution leg from conflicting work.","standalone":"Use the local ledger for a workflow that needs durable attempts and explicit transitions.","dependencies":"Local storage needs no peers. Applications supply the evidence for terminal transitions; a remote provider can replace local storage.","limit":"Local persistence is scoped to this app and origin. It is not a distributed database or a cross-device lock. A timeout does not release an unresolved leg.","methods":["status","reserve","read","beginAttempt","transition","trace"]},{"id":"sentinel","name":"Sentinel","role":"Policy & preflight","description":"Check exact SOL or SPL-token payments, per-mint limits, fees, rent and account state.","standalone":"Evaluate declared metadata, or decode and simulate a supported serialized SOL or SPL-token payment.","dependencies":"RPC simulation uses Conduit in a compatible network or your configured adapter. Edge devnet requires transfer verification.","limit":"Token preflight requires Conduit, a configured per-mint atomic ceiling, verified mint/account state, sufficient SOL fees/rent, and simulation of the exact bytes. A policy pass never grants wallet authority.","methods":["status","evaluate","preflight"]},{"id":"latch","name":"Latch","role":"Wallet authority","description":"Manage wallets and approve exact devnet SOL or explicitly allowed SPL-token payments.","standalone":"Manage device wallets or connect a compatible Wallet Standard provider. Request approval for one exact devnet transaction.","dependencies":"Device-wallet signing requires Conduit for devnet verification. Wallet Standard needs a compatible provider exposed in the owning browser or host. Native MWA remains a host implementation contract.","limit":"Devnet device keys are stored unencrypted. Mainnet management requires password encryption and a prominent loss warning; mainnet signing is disabled. The older temporary provider still loses its key on reload. This alpha is not an audited wallet. Explicit damaged-store recovery requires a verified independent backup and retains the original bytes before replacement. Other wallets require separate backups; payment and signing history is preserved. Token signing also requires its own per-mint atomic limits; the confirmation names the mint, accounts and amount.","methods":["status","authorise","connect","walletList","walletCreate","walletImport","walletSelect","walletRename","walletRemove","walletUnlock","walletLock","walletExport","walletConnectExternal","walletDisconnectExternal","walletRecoveryStatus","walletRecover"]},{"id":"dispatch","name":"Dispatch","role":"Submission","description":"Records a bounded attempt before sending and retains the signature when a reply is lost.","standalone":"Submit already signed bytes through a selected transport; read or reconcile the same attempt later.","dependencies":"Direct chain submission uses Conduit. Arena mode uses Arena. Reconciliation can use Witness; an external adapter can implement the provider.","limit":"Dispatch never signs. A lost response is unknown, not permission to construct another payment. Mainnet writes need explicit gates outside this Lab.","methods":["status","submit","read","reconcile"]},{"id":"conduit","name":"Conduit","role":"RPC transport","description":"Read wallet balances, token accounts and activity through your configured RPC connection.","standalone":"Use public reads or an explicitly enabled write path without Edge. Settings belong to the Sidecar.","dependencies":"Direct HTTP mode needs a reachable endpoint; external mode needs your adapter. Offline mode does not make network calls.","limit":"Bounded RPC reads with observed network identity. Token listings cover the original Token Program and report truncation; address activity is cursor-paged RPC history, not a complete indexer or background subscription.","methods":["status","request","verifyNetwork","inspect","openSettings","balance","asset","tokenAccounts","activity","transaction"]},{"id":"witness","name":"Witness","role":"Observation & receipts","description":"Observe transactions and independently verify a saved payment request against the recipient’s credited balance.","standalone":"Observe a recorded attempt, append compact evidence, and read receipts or an evidence trace.","dependencies":"Live observation uses Conduit or a configured adapter. Simulation observation uses Arena. Locally appended evidence needs no RPC.","limit":"Independent payment verification reads RPC bytes and recipient balance changes against a trusted saved request. It does not trust imported receipts, fulfil an order or replace a merchant’s durable invoice/signature claim. Token-2022 and transactions with lookup tables or unknown instructions are rejected.","methods":["status","observe","appendEvidence","receipt","readReceipt","trace","transactionEvidence","verifyPayment"]},{"id":"accord","name":"Accord","role":"Collective review","description":"Binds group approvals to a particular message, attempt, policy and wallet.","standalone":"Rehearse a quorum and audit which reviewer labels approved the same request.","dependencies":"Local control mode needs no peers. Apps explicitly enforce the decision before Latch. Real member authentication and threshold signing need a trusted provider.","limit":"The included local reviewers are simulated identities. Two names on a request are not two cryptographic signatures.","methods":["status","createGroup","group","request","approve","quorum"]},{"id":"switchyard","name":"Switchyard","role":"Resource lifecycle","description":"Allocates execution buckets to positions and records close, sweep and return to reuse.","standalone":"Manage the off-chain lifecycle of a finite execution resource.","dependencies":"Local allocation needs no peers. The app supplies execution evidence from Arena or a real service.","limit":"A bucket is a record, not an on-chain vault. Changing its lifecycle does not move funds. Position identity remains historical when a resource is reused.","methods":["status","allocate","read","transition","manifest"]},{"id":"arena","name":"Arena","role":"Deterministic execution","description":"Runs repeatable payment and position scenarios, including response loss, without a network.","standalone":"Test an unavailable venue or a recovery path with explicit simulated outcomes.","dependencies":"No network and no required peer. Apps can pair it with Circuit, Switchyard and Witness.","limit":"Its trades, P&L and settlement are simulations. A 1/10,000 devnet evidence transfer proves only that small transfer and its memo.","methods":["status","execute","read","position","evidenceTransfer"]},{"id":"market","name":"Market Pulse","role":"Market observations","description":"Shares one bounded price feed across charts and app consumers. Builds sampled OHLC candles from observed prices.","standalone":"Use prices and a chart directly, or freeze an observation into a simulated position action.","dependencies":"Needs a configured supported price provider. It is independent of the eleven Solana APIs and does not require Conduit.","limit":"Sampled candles are not exchange trade history. Missing intervals remain gaps; stale data blocks new Lab position actions. No historical volume is invented.","methods":["status","quote","candles","configuration","acquire","subscribe"]}],"flows":{"payment":{"title":"Payment → receipt","nodes":["edge","compass","circuit","sentinel","latch","dispatch","conduit","witness"],"scope":"Devnet SOL and an operation-bound memo. Every signature and send is explicit.","steps":[{"node":"circuit","label":"Reserve","text":"Save one operation ID before preparation. Replay the same ID with the same intent."},{"node":"sentinel","label":"Review","text":"Verify the transfer, memo, network and policy; freeze the message."},{"node":"latch","label":"Approve","text":"Ask the wallet to sign the exact reviewed message."},{"node":"dispatch","label":"Submit","text":"Persist the attempt, then send through Conduit. Lost replies remain unresolved."},{"node":"witness","label":"Observe","text":"Check signature status and exact confirmed bytes. Retain a bound receipt."},{"node":"edge","label":"Return","text":"Return the result to the app. On refresh, observe the same operation; never silently replace it."}]},"service":{"title":"Service → delivery → proof","nodes":["edge","circuit","sentinel","latch","dispatch","conduit","witness"],"scope":"Local report delivery is an application demonstration, not a production paywall. Proof records a digest, not authorship.","steps":[{"node":"circuit","label":"Order","text":"Persist a service order, its input digest and payment identity."},{"node":"edge","label":"Pay","text":"Use the reviewed devnet payment path, with the order commitment in the memo."},{"node":"witness","label":"Gate delivery","text":"Require the observed receipt to match this order’s exact transfer."},{"node":"witness","label":"Deliver","text":"Create the deterministic JSON report once and retain its application evidence."},{"node":"edge","label":"Anchor","text":"Start a separate, explicitly approved document commitment for the delivered report."},{"node":"witness","label":"Compare","text":"Compare the report bytes with the on-chain commitment, keeping both operations linked."}]},"positions":{"title":"Market → position → reuse","nodes":["market","compass","circuit","sentinel","switchyard","arena","witness"],"scope":"The application composes this recipe directly. Market prices are observations; execution and settlement stay in Arena.","steps":[{"node":"market","label":"Sample","text":"Take a fresh SOL price observation; freeze it for this action."},{"node":"compass","label":"Shape","text":"Classify open, reduce or close while preserving position identity."},{"node":"circuit","label":"Reserve","text":"Reserve this action, and allocate a resource through Switchyard."},{"node":"sentinel","label":"Check","text":"Check the action’s supplied risk metadata."},{"node":"arena","label":"Execute","text":"Apply the deterministic simulated action once, then retain Witness evidence."},{"node":"switchyard","label":"Reuse","text":"Close and sweep before releasing the resource. Keep the prior position history."}]},"recovery":{"title":"Lost response → recovery","nodes":["edge","circuit","dispatch","arena","witness"],"scope":"An isolated, deliberately simulated failure. It never modifies the devnet provider or replaces an installed runtime.","steps":[{"node":"circuit","label":"Record","text":"Save the operation and attempt before the effect."},{"node":"arena","label":"Lose reply","text":"Arena records execution, then the response disappears."},{"node":"dispatch","label":"Mark unknown","text":"Retain uncertainty with the original identity."},{"node":"witness","label":"Reconcile","text":"Observe that same attempt without another send."},{"node":"edge","label":"Resume","text":"Return the retained outcome to the app after refresh."}]}},"topics":[{"id":"start","title":"Start here","summary":"Select a recipe, then the capabilities it needs.","paragraphs":["For a standalone browser Lab, the shipped runtimes load with the reviewed devnet profile. For installed Lab, select the Solana Lab preset, compile this web project and rebuild the installer. It uses the owning installed runtime; missing providers do not trigger a browser replacement.","Open Wallets to create a saved devnet wallet, fund it from the faucet, then choose an existing funded recipient. Back up the wallet before clearing app data. A self-transfer records a memo but pays nobody else; fees are additional.","New devnet operations require Sentinel to allow the System program and Memo program (MemoSq4gqABAXKb96qnH8TysNcWxMyWCqXgDLGmfcHr). The Lab preset includes both. Existing custom settings are preserved; update them explicitly if policy blocks a new memo.","Begin with Service desk for a connected journey, or Pocket checkout for a single transfer. Review, sign, send and reconcile are separate controls. Nothing in the architecture map submits a transaction."]},{"id":"lifecycle","title":"Operations and recovery","summary":"Make identity survive the failure.","paragraphs":["Persist an operation ID and the intended sender, recipient, amount and commitment before preparation. Reuse that identity for the same work. A different intent must not overwrite an existing operation.","Edge’s devnet states include prepared, preflighted, authority-pending, authorised, submitting, submitted, unknown, confirmed, finalised, blocked, failed and expired. Not every provider supports every state. Keep the returned state and error together.","After submission or a lost response, call transactionStatus with the existing operation ID. Do not call prepare with a new ID as an automatic retry. A missing observation remains unresolved.","New transactions include a memo bound to operation ID and request digest. Distinct operations with identical amounts remain distinct even when they use the same blockhash. Persisted prepared transactions retain their bytes.","Local ledgers depend on app/origin storage. Export records before moving devices or clearing data. Browser tab locks coordinate this Lab where Web Locks is available; Sidecar local storage is not a distributed locking service."]},{"id":"dependencies","title":"Choose your Sidecars","summary":"Provider modes determine dependencies.","paragraphs":["You do not need all eleven for every app. Conduit alone supports RPC reads. Compass alone shapes intent; Circuit tracks a local operation; Accord rehearses member approval; Switchyard manages resource records; Arena simulates execution.","Edge devnet composes Circuit, Sentinel, Latch, Dispatch, Witness and Conduit. Compass is optional. Accord and Switchyard are application-composed extensions, not implicit prerequisites of every payment.","For positions, Solana Lab calls Compass, Circuit, Sentinel, Switchyard, Arena and Witness itself and consumes Market Pulse separately. An optional evidence transfer then uses Edge’s devnet path.","An external adapter can replace a provider, but its authentication, availability and production guarantees are yours to implement and test. Selecting a component does not deploy a managed service."]},{"id":"receipts","title":"What a receipt establishes","summary":"A successful send response is only one fact.","paragraphs":["For live Edge operations, Witness checks genesis, signature observation and equality of the complete signed transaction bytes returned by RPC. A usable receipt must also meet the configured commitment.","The helper hasBoundDevnetReceipt checks field binding on trusted Edge/Witness output. It does not authenticate arbitrary imported JSON. A remote merchant must independently verify the chain transaction, expected network, recipient, amount, commitment and single-use fulfilment.","Local Accord reviews, Arena outcomes and application evidence keep their original scope. A hash does not transform a simulation or an application assertion into a chain fact.","A document memo commits a namespace and SHA-256 digest of exact UTF-8 bytes. It establishes a recorded commitment; it does not establish the author, truth, ownership or confidentiality of the document."]},{"id":"recipes","title":"Connected service recipes","summary":"Three reusable handoffs.","paragraphs":["Service desk: persist a JSON report order → review its devnet payment → reconcile the exact receipt → generate the report → append delivery evidence → optionally anchor the report in Proof studio. Repeat delivery returns the same artifact.","Payout desk: reserve a batch and every child ID before work starts. Prepare, approve, send and reconcile each item separately. A partial batch is not rolled back, and confirmed items are not resent. It is not an atomic multi-recipient transaction.","Proof studio: hash bounded text locally → prepare a small devnet transfer with the document commitment → obtain an observed receipt → compare another copy of the text. The document itself is never put in the memo.","Position studio: capture a fresh price → simulate open/reduce/close in Arena → retain evidence → sweep the off-chain bucket for reuse. The optional 1/10,000 transfer is a separate payment, not a trade settlement."]},{"id":"sdk","title":"Application client","summary":"A thin interface over declared APIs.","paragraphs":["Use createSolanaClient(() => window.capp.solana) with the API belonging to your app. Its method allowlist is shared with the Lab. available() reports method presence; call status for provider readiness.","The client validates bounded JSON arguments and preserves the method receiver. It does not start providers, add permissions, approve signatures, retry sends or conceal missing Sidecars.","Market Pulse has its own client API and shared polling lifecycle. The eleven Solana Sidecars are exposed at window.capp.solana. Code examples here assume those APIs are present in the owning app.","Typed method names and JSON inputs are provided as a small source SDK. Provider-specific result shapes remain versioned runtime contracts; this is not a generated full schema binding."]},{"id":"providers","title":"Providers and distribution","summary":"Keep network and authority explicit.","paragraphs":["Configure RPC endpoints and the chosen distributable client token in Conduit. Inspect the payment connection there. The advanced read-only connection cannot change the build-owned payment network or submit transactions.","A distributed token is extractable. This version does not issue ephemeral provider tokens. Deploying your own authenticated adapter or credential broker is a separate integration.","Local AI is optional and can explain guidance and inspect bounded read tools. It does not gain wallet authority or submit these workflows. Guide teaches the same recipes and links to developer docs.","The included tests use actual runtimes with deterministic RPC fixtures. They establish behavior under those fixtures; installed Windows/Android, production wallet and live provider acceptance must be checked on those targets.","Latch device-wallet mode stores devnet keypairs in app data and mainnet keypairs as AES-256-GCM ciphertext derived from a user password with PBKDF2-SHA256 (600,000 iterations). This is experimental custody, not an audited wallet or hardware-backed key store. Mainnet accounts support create/import, receive, balance, lock/unlock and backup/export; mainnet signing remains disabled.","Wallet Standard discovery can connect compatible wallets exposed in the owning browser or host, including Solflare when it advertises the selected network and signTransaction feature. Missing providers remain unavailable. This does not add native Android MWA or a mobile deeplink transport. Wallet accounts and exact returned signed bytes are checked before accepting a devnet signature.","Call walletCreate, walletImport, walletUnlock and walletExport directly from an explicit owner UI. Never send their input or result to activity logs, an assistant, analytics or receipt exports. Encrypted backups require their password; raw keypair exports are explicitly confirmed and unencrypted. Wallet labels and addresses are public metadata, not secrets."]},{"id":"asset-payments","title":"Asset-aware payments and independent verification","summary":"Build token payments and invoices from the existing Sidecars. No additional Sidecar or custom indexer is required.","paragraphs":["A token is identified by network, genesis, mint and program; amounts are exact unsigned integer strings. Conduit reads mint precision and account state. Sentinel checks the configured mint ceiling, network fee and possible recipient account rent before Latch signs the exact reviewed bytes.","Compass creates a Solana Pay transfer request with a durable reference. Edge can prepare its payment, while Witness can verify a payer’s independently submitted transaction against the trusted saved terms and actual recipient credit. Remote fulfilment still needs a server-owned atomic invoice/signature claim; local client state is not that authority.","See [asset payment integration](SOLANA_ASSET_PAYMENTS.md) for build settings, API examples, supported wallet transaction forms, read limits and remaining native qualification."]},{"id":"expired-review","title":"Recover an expired review","summary":"A short-lived transaction review may expire before any submission. Refresh that review explicitly; reconcile an uncertain send.","paragraphs":["Edge checks blockhash validity before wallet approval and records expired state when the transaction was never submitted. Use edge.refresh({operationId}) only on an expired, never-submitted operation. It retains the old record, returns one durable successor and keeps the saved sender, recipient, asset, amount, commitment and logical leg. Repeat calls resume the same successor. Save its returned operationId in the application workflow, then run preflight and request new wallet and team approvals. Refresh never signs or sends.","A Circuit attempt, unknown authority outcome or submitted transaction prevents refresh, even if its blockhash is now old. Keep reconciling its original signature. A payment request’s own expiry is separate and cannot be extended by refreshing its transaction.","Latch walletCreate({network:\"devnet\",label:\"Receiver\",select:false}) can create a test receiver without changing the payer. Check status.walletCreateKeepsSelection first. No token balance or permission is implied, and backups remain the user’s responsibility."]}],"references":[{"title":"Solana transaction structure and atomicity","url":"https://solana.com/docs/core/transactions"},{"title":"Confirmed transaction RPC response","url":"https://solana.com/docs/rpc/http/gettransaction"},{"title":"Memo program","url":"https://www.solana-program.com/docs/memo"},{"title":"Solana SPL token transfers","url":"https://solana.com/docs/tokens/basics/transfer-tokens"},{"title":"Solana Pay transfer requests","url":"https://docs.solanapay.com/spec"}]};
/* Shared cApp / Solana Lab architecture explorer. Static authored content only. */
(() => {
  const data = globalThis.CappSolanaDocs;
  const escape = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  if (!globalThis.customElements || customElements.get('capp-solana-map')) return;
  class SolanaMap extends HTMLElement {
    connectedCallback() {
      if (this.bound) return;this.bound=true;
      this.flow='payment';this.step=0;this.node=this.getAttribute('focus-node')||'edge';
      this.addEventListener('click',event=>{
        const node=event.target.closest('[data-map-node]'), flow=event.target.closest('[data-map-flow]'), step=event.target.closest('[data-map-step]');
        if(node){this.node=node.dataset.mapNode;this.render('node');}
        if(flow){this.flow=flow.dataset.mapFlow;this.step=0;this.node=data.flows[this.flow].steps[0].node;this.render('flow');}
        if(step){this.step=Number(step.dataset.mapStep);this.node=data.flows[this.flow].steps[this.step].node;this.render('step');}
      });this.render();
    }
    render(focus) {
      const flow=data.flows[this.flow], node=data.components.find(c=>c.id===this.node)||data.components[0], step=flow.steps[this.step];
      const tile=id=>{const c=data.components.find(c=>c.id===id);return `<button type="button" class="sm-node ${flow.nodes.includes(id)?'sm-used':''}" data-map-node="${id}" aria-pressed="${node.id===id}"><b>${escape(c.name)}</b><small>${escape(c.role)}</small></button>`;};
      this.innerHTML=`<div class="sm"><div class="sm-top"><div><span class="sm-kicker">INTERACTIVE ARCHITECTURE</span><h2>One operation. Clear boundaries.</h2><p>Select a recipe, then inspect a component or walk its path.</p></div><span class="sm-legend">● Used by this recipe · Illustration, no transactions</span></div>
      <div class="sm-tabs" role="group" aria-label="Architecture recipes">${Object.entries(data.flows).map(([id,f])=>`<button type="button" data-map-flow="${id}" aria-pressed="${this.flow===id}">${escape(f.title)}</button>`).join('')}</div>
      <div class="sm-workspace"><div class="sm-diagram"><div class="sm-app">Your application <small>Owns the use case, user choices and delivery</small></div><div class="sm-connector" aria-hidden="true">↓</div><div class="sm-edge">${tile('edge')}<p>Optional coordinator · six required live peers for devnet</p></div>
      <svg class="sm-branches" viewBox="0 0 600 32" aria-hidden="true" preserveAspectRatio="none"><path d="M300 0v12H100v18m200-18v18m0-18h200v18" fill="none" stroke="currentColor" stroke-width="1.5"/></svg>
      <div class="sm-lanes"><div><span class="sm-label">Prepare & check</span>${['compass','circuit','sentinel'].map(tile).join('')}</div><div><span class="sm-label">Approve & submit</span>${['latch','dispatch','conduit'].map(tile).join('')}</div><div><span class="sm-label">Observe & return</span>${tile('witness')}<div class="sm-return">↑ Result to the app<p>Deliver, reconcile, or wait on the same operation.</p></div></div></div>
      <div class="sm-support"><span class="sm-label">App-composed extensions · only where the recipe needs them</span><div>${['accord','switchyard','arena','market'].map(tile).join('')}</div></div></div>
      <section class="sm-detail" aria-label="Selected Sidecar"><span class="sm-kicker">${escape(node.role)}</span><h3>${escape(node.name)}</h3><p>${escape(node.description)}</p><h4>Use it on its own</h4><p>${escape(node.standalone)}</p><h4>When peers are needed</h4><p>${escape(node.dependencies)}</p><details open><summary>Available calls</summary><div class="sm-methods">${node.methods.map(m=>`<code>${escape(m)}</code>`).join('')}</div></details><p class="sm-boundary">${escape(node.limit)}</p></section></div>
      <div class="sm-walk"><div class="sm-step-buttons" role="group" aria-label="Operation steps">${flow.steps.map((s,i)=>`<button type="button" data-map-step="${i}" aria-pressed="${i===this.step}">${i+1}. ${escape(s.label)}</button>`).join('')}</div><p aria-live="polite"><b>${escape(step.label)}.</b> ${escape(step.text)}</p><small>${escape(flow.scope)}</small></div></div>`;
      if(focus){const selector={node:`[data-map-node="${node.id}"]`,flow:`[data-map-flow="${this.flow}"]`,step:`[data-map-step="${this.step}"]`}[focus];this.querySelector(selector)?.focus({preventScroll:true});}
    }
  }
  customElements.define('capp-solana-map',SolanaMap);
})();
